from collections import deque


def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    char_to_idx = {ch: idx for idx, ch in enumerate(alphabet)}
    k = len(alphabet)

    nxt = [[-1] * k]
    bad = [False]

    for word in banned:
        node = 0
        for ch in word:
            c = char_to_idx[ch]
            if nxt[node][c] == -1:
                nxt[node][c] = len(nxt)
                nxt.append([-1] * k)
                bad.append(False)
            node = nxt[node][c]
        bad[node] = True

    num_nodes = len(nxt)
    fail = [0] * num_nodes
    queue = deque()

    for c in range(k):
        child = nxt[0][c]
        if child != -1:
            fail[child] = 0
            queue.append(child)
        else:
            nxt[0][c] = 0

    while queue:
        u = queue.popleft()
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = nxt[u][c]
            if v != -1:
                if bad[u]:
                    bad[v] = True
                fail[v] = nxt[fail[u]][c]
                queue.append(v)
            else:
                nxt[u][c] = nxt[fail[u]][c]

    good = [i for i in range(num_nodes) if not bad[i]]
    state_id = {u: idx for idx, u in enumerate(good)}
    m = len(good)

    mat = [[0] * m for _ in range(m)]
    for i, u in enumerate(good):
        for c in range(k):
            v = nxt[u][c]
            if not bad[v]:
                mat[i][state_id[v]] += 1

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for t in range(m):
                ait = ai[t]
                if ait:
                    bt = b[t]
                    for j in range(m):
                        ri[j] += ait * bt[j]
            for j in range(m):
                ri[j] %= MOD
        return res

    def vec_mul(v: list[int], a: list[list[int]]) -> list[int]:
        res = [0] * m
        for t in range(m):
            vt = v[t]
            if vt:
                at = a[t]
                for j in range(m):
                    res[j] += vt * at[j]
        return [x % MOD for x in res]

    vec = [0] * m
    vec[0] = 1
    power = n
    base = mat
    while power > 0:
        if power & 1:
            vec = vec_mul(vec, base)
        power >>= 1
        if power > 0:
            base = mat_mul(base, base)

    return sum(vec) % MOD
